21:   const [isLeaving, setIsLeaving] = useState(false);
22: 
23:   const selectedCount = Object.values(selections).reduce((a, b) => a + b, 0);
24:   const selectedTotal = dailyOptions
25:     .filter((o) => selections[o.id])
26:     .reduce((sum, o) => sum + o.price * selections[o.id], 0);
27: 
28:   function handleAddToCart() {
29:     // Try to submit to Real API cart endpoint
30:     setIsSubmitting(true);
31:     setTimeout(() => setIsSubmitting(false), 2500);
