46:       </div>
47:       <div className="grid-wrapper">
48:         <CurrentMealOptionCard />
49:         <div className="daily-options-grid">
50:           {dailyOptions.map((option) => {
51:             const qty = selections[option.id] || 0;
52:             return (
53:               <MealOptionCard
54:                 key={option.id}
55:                 option={option}
56:                 qty={qty}
57:                 setSelections={setSelections}
58:               />
59:             );
60:           })}
61:         </div>
62:       </div>
63: 
64:       {selectedCount > 0 && (
65:         <div className={`cart-float ${isLeaving ? "is-leaving" : ""}`}>
66:           <div className="cart-float-info">
67:             <span className="cart-float-count">
68:               {selectedCount} item{selectedCount > 1 ? "s" : ""}
69:             </span>
70:             <span className="cart-float-total">
71:               KSh {selectedTotal.toLocaleString()}
72:             </span>
73:           </div>
