76:             onClick={() => handleAddToCart()}
77:           >
78:             {isSubmitting
79:               ? "Adding..."
80:               : addedToCart
81:                 ? "Added successfully!"
82:                 : "Add to cart"}
83:           </button>
84:         </div>
85:       )}
86:     </section>
87:   );
88: }
